<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\TrustedClient\Domain\TrustedClientIdTokenSignedResponseAlgOptions;
use Civi\Lughauth\Features\Access\TrustedClient\Domain\ValueObject\Accessor\TrustedClientIdTokenSignedResponseAlgAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TrustedClientIdTokenSignedResponseAlgAccessor trait.
 *
 * Covers null default, string/VO assignment via withIdTokenSignedResponseAlg,
 * getIdTokenSignedResponseAlg/idTokenSignedResponseAlg accessors, and isIdTokenSignedResponseAlgChanged with/without original.
 */
class TrustedClientIdTokenSignedResponseAlgAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withIdTokenSignedResponseAlg creates a new instance with the IdTokenSignedResponseAlg set
     * from a string value, and getIdTokenSignedResponseAlg returns the primitive string.
     */
    public function testWithIdTokenSignedResponseAlgFromString(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientIdTokenSignedResponseAlgAccessorUnitTest();

        // Act
        $result = $holder->withIdTokenSignedResponseAlg(TrustedClientIdTokenSignedResponseAlgOptions::RS256);

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(TrustedClientIdTokenSignedResponseAlgOptions::RS256, $result->getIdTokenSignedResponseAlg());
    }
    /**
     * Asserts that withidTokenSignedResponseAlg has access to the value object
     * from a string value, and getIdTokenSignedResponseAlg returns the primitive string.
     */
    public function testWithIdTokenSignedResponseAlgFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientIdTokenSignedResponseAlgAccessorUnitTest();

        // Act
        $result = $holder->withIdTokenSignedResponseAlg(TrustedClientIdTokenSignedResponseAlgOptions::RS256);

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(TrustedClientIdTokenSignedResponseAlgOptions::RS256, $result->idTokenSignedResponseAlg()->value());
    }
    public function testChangedIdTokenSignedResponseAlg(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientIdTokenSignedResponseAlgAccessorUnitTest();
        $original = $holder->withIdTokenSignedResponseAlg(TrustedClientIdTokenSignedResponseAlgOptions::RS256);
        $same = $holder->withIdTokenSignedResponseAlg(TrustedClientIdTokenSignedResponseAlgOptions::RS256);
        $modified = $holder->withIdTokenSignedResponseAlg(TrustedClientIdTokenSignedResponseAlgOptions::ES256);

        // Act
        $unchanged = $holder->isIdTokenSignedResponseAlgChanged();
        $withSame = $original->isIdTokenSignedResponseAlgChanged($same);
        $withDiferent = $original->isIdTokenSignedResponseAlgChanged($modified);

        // Assert
        $this->assertFalse($unchanged);
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithTrustedClientIdTokenSignedResponseAlgAccessorUnitTest
{
    use TrustedClientIdTokenSignedResponseAlgAccessor;
}
